export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategorySpec {
  maxNights: number;
  minNights?: number;
  maxGuests: number;
  perNight: number;
  highNight: number;
  surchargePerGuest: number;
  flatFee: number;
}

// A quote for any category is: base per night (+ high-season surplus),
// minus a loyalty/VIP discount, plus any guest surcharge and fixed fee.
// Terms and discount/policy rules are identical across categories, so only
// the numeric limits live in this lookup.
const CATEGORIES: Record<string, CategorySpec> = {
  standard: { maxNights: 14, maxGuests: 2, perNight: 80, highNight: 30, surchargePerGuest: 0, flatFee: 0 },
  suite: { maxNights: 21, maxGuests: 4, perNight: 150, highNight: 60, surchargePerGuest: 25, flatFee: 0 },
  villa: { maxNights: 28, minNights: 3, maxGuests: 8, perNight: 300, highNight: 120, surchargePerGuest: 0, flatFee: 500 },
};

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const spec = CATEGORIES[req.category as string];
  if (!spec) {
    return { ok: false, error: "unknown category" };
  }

  const name = req.category as string;
  const nights = req.nights as number;
  const guests = req.guests as number;
  const years = req.loyaltyYears as number;
  const season = req.season;
  const vip = req.coupon === "VIP";

  if (!Number.isInteger(req.nights) || nights < 1 || nights > spec.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (spec.minNights !== undefined && nights < spec.minNights) {
    return { ok: false, error: "villa minimum stay" };
  }
  if (!Number.isInteger(req.guests) || guests < 1 || guests > spec.maxGuests) {
    return { ok: false, error: "bad guests" };
  }
  if (season !== "low" && season !== "high") {
    return { ok: false, error: "bad season" };
  }

  let total = spec.perNight * nights;
  if (season === "high") {
    total = total + spec.highNight * nights;
  }
  if (vip || years >= 3) {
    total = total - Math.floor(total / 10);
  }
  if (guests > 2) {
    total = total + spec.surchargePerGuest;
  }
  total = total + spec.flatFee;

  // The discount and cancellation terms share one condition; villa's
  // "loyalty > 2" and standard/suite's "loyalty >= 3" are identical for
  // integer years, so a single VIP-or-membership test drives both.
  const policy = vip || years >= 3 ? "flex" : "strict";
  const line = name + ":" + String(nights) + "n:" + String(total) + ":" + policy;
  return { ok: true, total, policy, line };
}

